  "heatmap": {
    "item": "heatmap",
    "code": "<script setup lang=\"ts\">\nimport { Heatmap, type HeatmapValue } from \"@/components/ui/heatmap\"\n\nfunction activity(): HeatmapValue[] {\n  const out: HeatmapValue[] = []\n  const today = new Date()\n  // A seeded wave, so the year looks lived in and stays the same per day.\n  for (let i = 0; i < 371; i++) {\n    const date = new Date(today.getFullYear(), today.getMonth(), today.getDate() - i)\n    const weekday = date.getDay()\n    const seed = Math.sin(i * 12.9898) * 43758.5453\n    const noise = seed - Math.floor(seed)\n    const busy = weekday === 0 || weekday === 6 ? 0.25 : 1\n    out.push({ date, value: noise > 0.35 ? Math.round(noise * 10 * busy) : 0 })\n  }\n  return out\n}\n\nconst data = activity()\nconst labels = {\n  value: (value: number, date: Date) =>\n    `${value} commits on ${date.toLocaleDateString([], { weekday: \"long\", day: \"numeric\", month: \"long\" })}`,\n}\n</script>\n\n<template>\n  <Heatmap :data=\"data\" class=\"max-w-3xl\" :labels=\"labels\" />\n</template>"
  },
  "image-cropper": {
    "item": "image-cropper",
    "code": "<script setup lang=\"ts\">\nimport { computed, ref } from \"vue\"\nimport type { AcceptableValue } from \"reka-ui\"\nimport { Button } from \"@/components/ui/button\"\nimport { ImageCropper, cropImage, type CropArea } from \"@/components/ui/image-cropper\"\nimport { ToggleGroup, ToggleGroupItem } from \"@/components/ui/toggle-group\"\n\nconst src = \"/images/hero.jpg\"\n\nconst ratio = ref(\"1\")\nconst area = ref<CropArea | null>(null)\nconst preview = ref<string | null>(null)\nconst aspect = computed(() => (ratio.value === \"free\" ? undefined : ratio.value === \"16/9\" ? 16 / 9 : 1))\n\nfunction pick(next: AcceptableValue[]) {\n  if (!next[0]) return\n  ratio.value = next[0] as string\n  preview.value = null\n}\n\nasync function crop() {\n  if (!area.value) return\n  const blob = await cropImage(src, area.value, { maxSize: 256, type: \"image/jpeg\" })\n  if (preview.value) URL.revokeObjectURL(preview.value)\n  preview.value = URL.createObjectURL(blob)\n}\n</script>\n\n<template>\n  <div class=\"flex w-full max-w-xl flex-col gap-3\">\n    <ToggleGroup aria-label=\"Ratio\" class=\"self-start\" :model-value=\"[ratio]\" @update:model-value=\"pick\">\n      <ToggleGroupItem value=\"1\">Avatar</ToggleGroupItem>\n      <ToggleGroupItem value=\"16/9\">16:9</ToggleGroupItem>\n      <ToggleGroupItem value=\"free\">Free</ToggleGroupItem>\n    </ToggleGroup>\n    <ImageCropper\n      :key=\"ratio\"\n      :src=\"src\"\n      alt=\"A painted landscape\"\n      :aspect=\"aspect\"\n      :shape=\"ratio === '1' ? 'round' : 'rect'\"\n      :max-height=\"300\"\n      @area-change=\"area = $event\"\n    />\n    <div class=\"flex items-center gap-3\">\n      <Button size=\"sm\" :disabled=\"!area\" @click=\"crop\">Crop</Button>\n      <span class=\"font-mono text-[11px] text-muted-foreground\">\n        {{ area ? `${area.width}×${area.height} at ${area.x},${area.y}` : \"…\" }}\n      </span>\n      <img\n        v-if=\"preview\"\n        :src=\"preview\"\n        alt=\"Cropped result\"\n        :class=\"ratio === '1' ? 'ms-auto size-12 rounded-full' : 'ms-auto h-12 rounded-lg'\"\n      />\n    </div>\n  </div>\n</template>"
  },
  "image-gallery": {
    "item": "image-gallery",
    "code": "<script setup lang=\"ts\">\nimport { ImageGallery, type GalleryImage } from \"@/components/ui/image-gallery\"\n\n/** Paper-toned abstract compositions, drawn inline so the demo needs no image files. */\nfunction art(hue: number, shape: \"circle\" | \"arc\" | \"bars\", label: string): string {\n  const ink = `oklch(0.45 0.12 ${hue})`\n  const wash = `oklch(0.93 0.04 ${hue})`\n  const paper = \"oklch(0.98 0.006 90)\"\n  const body =\n    shape === \"circle\"\n      ? `<circle cx=\"560\" cy=\"360\" r=\"220\" fill=\"${ink}\"/><circle cx=\"380\" cy=\"470\" r=\"120\" fill=\"${wash}\" opacity=\".9\"/>`\n      : shape === \"arc\"\n        ? `<path d=\"M120 640 A440 440 0 0 1 1000 640\" fill=\"none\" stroke=\"${ink}\" stroke-width=\"90\"/><rect x=\"460\" y=\"160\" width=\"200\" height=\"200\" rx=\"40\" fill=\"${wash}\"/>`\n        : `<rect x=\"200\" y=\"200\" width=\"120\" height=\"440\" rx=\"60\" fill=\"${ink}\"/><rect x=\"380\" y=\"300\" width=\"120\" height=\"340\" rx=\"60\" fill=\"${wash}\"/><rect x=\"560\" y=\"140\" width=\"120\" height=\"500\" rx=\"60\" fill=\"${ink}\" opacity=\".6\"/>`\n  const svg = `<svg xmlns=\"http://www.w3.org/2000/svg\" viewBox=\"0 0 1120 800\" role=\"img\" aria-label=\"${label}\"><rect width=\"1120\" height=\"800\" fill=\"${paper}\"/><rect width=\"1120\" height=\"800\" fill=\"${wash}\" opacity=\".35\"/>${body}</svg>`\n  return `data:image/svg+xml;utf8,${encodeURIComponent(svg)}`\n}\n\nconst images: GalleryImage[] = [\n  { src: art(277, \"circle\", \"Indigo circles\"), alt: \"Two indigo circles on paper\", caption: \"Indigo, ink and wash\" },\n  { src: art(165, \"arc\", \"Jade arc\"), alt: \"A jade arc over a soft square\", caption: \"Jade arc\" },\n  { src: art(38, \"bars\", \"Orange bars\"), alt: \"Three orange pill bars\", caption: \"Orange bars\" },\n  { src: art(223, \"arc\", \"Cyan arc\"), alt: \"A cyan arc over a soft square\", caption: \"Cyan arc\" },\n  { src: art(15, \"circle\", \"Crimson circles\"), alt: \"Two crimson circles on paper\", caption: \"Crimson, ink and wash\" },\n  { src: art(90, \"bars\", \"Paper bars\"), alt: \"Three warm grey pill bars\", caption: \"Paper bars\" },\n]\n</script>\n\n<template>\n  <ImageGallery :images=\"images\" class=\"w-full max-w-md\" />\n</template>"
  },
