  "message-scroller": {
    "item": "message-scroller",
    "code": "<script setup lang=\"ts\">\nimport { onBeforeUnmount, onMounted, ref } from \"vue\"\n\nimport { MessageScroller } from \"@/components/ui/message-scroller\"\n\nconst lines = ref(Array.from({ length: 6 }, (_, i) => `Line ${i + 1}`))\nlet id: ReturnType<typeof setInterval> | undefined\nonMounted(() => {\n  id = setInterval(() => {\n    if (lines.value.length <= 60) lines.value.push(`Line ${lines.value.length + 1}`)\n  }, 900)\n})\nonBeforeUnmount(() => clearInterval(id))\n</script>\n\n<template>\n  <MessageScroller class=\"h-48 w-full max-w-md rounded-2xl border border-border\" aria-label=\"Streaming log\">\n    <ol class=\"m-0 flex list-none flex-col gap-1 p-3 font-mono text-xs text-muted-foreground\">\n      <li v-for=\"line in lines\" :key=\"line\">{{ line }}</li>\n    </ol>\n  </MessageScroller>\n</template>"
  },
  "message": {
    "item": "message",
    "code": "<script setup lang=\"ts\">\nimport { RefreshCw, ThumbsUp } from \"@lucide/vue\"\n\nimport { Avatar, AvatarFallback } from \"@/components/ui/avatar\"\nimport { Button } from \"@/components/ui/button\"\nimport { CopyButton } from \"@/components/ui/copy-button\"\nimport {\n  Message, MessageActions, MessageAvatar, MessageBody, MessageContent,\n} from \"@/components/ui/message\"\n\nconst answer =\n  \"Use a Split Button when one action is the obvious one and the others are variants of it, like publishing now or later. If the actions are unrelated, a Menu on its own reads better.\"\n</script>\n\n<template>\n  <div class=\"flex w-full max-w-md flex-col gap-6\">\n    <Message from=\"user\">\n      <MessageBody>\n        <MessageContent>When should I use a Split Button?</MessageContent>\n      </MessageBody>\n    </Message>\n    <Message from=\"assistant\">\n      <MessageAvatar>\n        <Avatar><AvatarFallback>L</AvatarFallback></Avatar>\n      </MessageAvatar>\n      <MessageBody>\n        <MessageContent>\n          <p>{{ answer }}</p>\n        </MessageContent>\n        <MessageActions>\n          <CopyButton :value=\"answer\" size=\"icon-xs\" />\n          <Button variant=\"ghost\" size=\"icon-xs\" aria-label=\"Regenerate\"><RefreshCw /></Button>\n          <Button variant=\"ghost\" size=\"icon-xs\" aria-label=\"Good answer\"><ThumbsUp /></Button>\n        </MessageActions>\n      </MessageBody>\n    </Message>\n  </div>\n</template>"
  },
